(()=>{
const main=document.querySelector('[data-science]');if(!main)return;
const isAwards=main.dataset.science==='distinctions';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const norm=s=>String(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const search=document.querySelector('#science-search'),year=document.querySelector('#science-year'),results=document.querySelector('#science-results'),counter=document.querySelector('#science-count'),prev=document.querySelector('#science-previous'),next=document.querySelector('#science-next'),pageLabel=document.querySelector('#science-page'),galleryNode=document.querySelector('#science-gallery'),galleryMore=document.querySelector('#gallery-more'),galleryCounter=document.querySelector('#gallery-count');
const params=new URLSearchParams(location.search);let scope='all',current=1,filtered=[],records=[],photos=[],galleryFiltered=[],galleryLimit=12,activeGalleryIndex=-1;
const labels=isAwards?{innovation:'Innovation & compétitions',these:'Prix de thèse',participation:'Participation & valorisation'}:{international:'Internationale',national:'Nationale'};
function present(html){if(dialog.open){content.innerHTML=html;dialog.scrollTop=0;document.querySelector('.close-dialog').focus()}else openDialog(html)}
function photoViewer(src,caption,index=-1){activeGalleryIndex=index;present(heading('GALERIE / ARCHIVES DU LRIT','En images')+`<figure class="science-lightbox"><img src="${esc(src)}" alt="${esc(caption)}"><figcaption>${esc(caption)}</figcaption></figure>${index>=0?`<div class="lightbox-navigation"><button class="button secondary" id="photo-previous" ${index===0?'disabled':''}>← Image précédente</button><span>${index+1} / ${galleryFiltered.length}</span><button class="button secondary" id="photo-next" ${index===galleryFiltered.length-1?'disabled':''}>Image suivante →</button></div>`:''}`);
 content.querySelector('#photo-previous')?.addEventListener('click',()=>galleryPhoto(index-1));content.querySelector('#photo-next')?.addEventListener('click',()=>galleryPhoto(index+1))}
function galleryPhoto(i){if(i<0||i>=galleryFiltered.length)return;const p=galleryFiltered[i];photoViewer(p.src,p.caption,i)}
dialog.addEventListener('close',()=>{activeGalleryIndex=-1});dialog.addEventListener('keydown',e=>{if(activeGalleryIndex>=0&&['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();galleryPhoto(activeGalleryIndex+(e.key==='ArrowRight'?1:-1))}});
function showItem(id){activeGalleryIndex=-1;const item=records.find(r=>r.id===id);if(!item)return;const category=isAwards?labels[item.category]:labels[item.scope];const visual=item.image?`<button class="detail-visual-button" aria-label="Agrandir le visuel" data-item-image><img class="detail-event-image" src="${esc(item.image)}" alt="${esc(item.title)}"><span>Agrandir le visuel ↗</span></button>`:'';
 const extra=(item.images||[]).map((src,i)=>`<button class="detail-extra" data-extra-image="${i}" aria-label="Agrandir le document complémentaire ${i+1}"><img src="${esc(src)}" alt="Document complémentaire : ${esc(item.title)}" loading="lazy"><span>Voir en grand ↗</span></button>`).join('');
 present(heading(`${category.toUpperCase()} / ${item.year}`,item.title)+`<div class="detail-event-meta"><span>${esc(item.date)}</span><span>${esc(item.place)}</span></div>${isAwards?`<div class="award-result-large">${esc(item.result)}</div>`:`<p class="event-kind">${esc(item.kind)}</p>`}${item.person?`<p class="laureate"><strong>Lauréat :</strong> ${esc(item.person)}</p>`:''}${visual}${item.description?`<p>${esc(item.description)}</p>`:''}${extra?`<h3>Autres visuels</h3><div class="detail-extra-grid">${extra}</div>`:''}<p class="directory-source">Source : documentation du laboratoire, chapitre Manifestations scientifiques.</p>`);
 content.querySelector('[data-item-image]')?.addEventListener('click',()=>photoViewer(item.image,item.title+' · '+item.date));content.querySelectorAll('[data-extra-image]').forEach(b=>b.addEventListener('click',()=>photoViewer(item.images[Number(b.dataset.extraImage)],item.title+' — document complémentaire')))}
function renderGallery(){galleryFiltered=photos.filter(p=>isAwards?p.scope==='distinction':p.scope!=='distinction'&&(scope==='all'||p.scope===scope));const list=galleryFiltered.slice(0,galleryLimit);galleryNode.innerHTML=list.map((p,i)=>`<button class="archive-image ${p.poster?'archive-poster':''}" data-gallery-index="${i}" aria-label="Agrandir : ${esc(p.caption)}"><span class="archive-thumb"><img src="${esc(p.src)}" alt="${esc(p.caption)}" loading="lazy"><span class="zoom-symbol">↗</span></span><span class="archive-caption">${esc(p.caption)}</span></button>`).join('');galleryCounter.textContent=`${list.length} visuels affichés sur ${galleryFiltered.length}`;galleryMore.hidden=list.length>=galleryFiltered.length;galleryNode.querySelectorAll('[data-gallery-index]').forEach(b=>b.addEventListener('click',()=>galleryPhoto(Number(b.dataset.galleryIndex))))}
function render(){const totalPages=Math.max(1,Math.ceil(filtered.length/9));current=Math.min(current,totalPages);const list=filtered.slice((current-1)*9,current*9);counter.textContent=`${filtered.length} ${isAwards?'notice':'manifestation'}${filtered.length>1?'s':''} affichée${filtered.length>1?'s':''} sur ${records.length}`;
results.innerHTML=list.length?list.map(item=>{const category=isAwards?item.category:item.scope;return `<article class="science-card ${isAwards?'award-card':''}"><button class="science-card-visual ${item.image?'has-image':'archive-cover'}" data-open-item="${esc(item.id)}" aria-label="Découvrir : ${esc(item.title)}">${item.image?`<img src="${esc(item.image)}" alt="${esc(item.title)}" loading="lazy">`:`<span class="archive-cover-grid" aria-hidden="true"></span><span class="archive-cover-year">${item.year}</span><span class="archive-cover-name">${esc(item.short||item.title)}</span><span class="archive-cover-brand">LRIT / ARCHIVES SCIENTIFIQUES</span>`}<span class="science-card-badge ${category}">${esc(isAwards?item.result:labels[category])}</span></button><div class="science-card-body"><div class="science-card-date"><span>${esc(item.date)}</span><span>${esc(isAwards?labels[category]:item.kind)}</span></div><h3>${esc(item.title)}</h3>${item.person?`<p class="science-card-person">${esc(item.person)}</p>`:''}<p class="science-card-place">${esc(item.place)}</p><button class="text-link" data-open-item="${esc(item.id)}">${isAwards?'Découvrir la distinction':'Voir les détails'} <span>↗</span></button></div></article>`}).join(''):'<div class="no-results"><h3>Aucun résultat.</h3><p>Essayez un autre mot-clé, une autre année ou une autre catégorie.</p></div>';
pageLabel.textContent=filtered.length?`Page ${current} sur ${totalPages}`:'Aucun résultat';prev.disabled=current<=1;next.disabled=current>=totalPages||!filtered.length;results.querySelectorAll('[data-open-item]').forEach(b=>b.addEventListener('click',()=>showItem(b.dataset.openItem)))}
function filter(){current=1;const q=norm(search.value.trim());filtered=records.filter(r=>(scope==='all'||(isAwards?r.category:r.scope)===scope)&&(year.value==='all'||String(r.year)===year.value)&&norm(`${r.title} ${r.place} ${r.person||''} ${r.short||''} ${r.result||''}`).includes(q)).sort((a,b)=>b.year-a.year);
 const p=new URLSearchParams();if(scope!=='all')p.set('scope',scope);if(year.value!=='all')p.set('annee',year.value);if(search.value.trim())p.set('q',search.value.trim());history.replaceState(null,'',location.pathname+(p.size?'?'+p:''));document.querySelectorAll('[data-scope]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.scope===scope)));render();galleryLimit=12;renderGallery()}
Promise.all([fetch(isAwards?'distinctions.json':'manifestations.json').then(r=>{if(!r.ok)throw Error();return r.json()}),fetch('galerie.json').then(r=>{if(!r.ok)throw Error();return r.json()})]).then(([data,images])=>{records=data;photos=images;[...new Set(records.map(r=>r.year))].sort((a,b)=>b-a).forEach(y=>{const o=document.createElement('option');o.value=String(y);o.textContent=y;year.append(o)});if(params.get('scope')==='all'||Object.keys(labels).includes(params.get('scope')))scope=params.get('scope');if([...year.options].some(o=>o.value===params.get('annee')))year.value=params.get('annee');search.value=params.get('q')||'';document.querySelectorAll('[data-scope]').forEach(b=>b.addEventListener('click',()=>{scope=b.dataset.scope;filter()}));search.addEventListener('input',filter);year.addEventListener('change',filter);document.querySelector('#science-reset').addEventListener('click',()=>{scope='all';year.value='all';search.value='';filter();search.focus()});prev.addEventListener('click',()=>{if(current>1){current--;render();counter.scrollIntoView({block:'start'})}});next.addEventListener('click',()=>{if(current<Math.ceil(filtered.length/9)){current++;render();counter.scrollIntoView({block:'start'})}});galleryMore.addEventListener('click',()=>{galleryLimit+=12;renderGallery()});filter()}).catch(()=>{counter.textContent='Les archives ne peuvent pas être chargées pour le moment.';prev.disabled=true;next.disabled=true;galleryMore.hidden=true});
})();
